create table todo_configuration_resource_item (
  resource_item_id bigint not null auto_increment,
  resource_type varchar(24) not null,
  resource_code varchar(128) not null,
  resource_name varchar(128) not null,
  description varchar(500) null,
  business_type varchar(32) not null,
  value_json json not null,
  status varchar(16) not null default 'ACTIVE',
  sort_order int not null default 0,
  version int not null default 0,
  create_by varchar(64) null,
  create_time datetime not null default current_timestamp,
  update_by varchar(64) null,
  update_time datetime null,
  primary key (resource_item_id),
  unique key uk_todo_config_resource (resource_type,business_type,resource_code),
  key idx_todo_config_resource_lookup (resource_type,business_type,status,sort_order),
  constraint chk_todo_config_resource_type check (resource_type in ('FIELD','MATERIAL','DOD_RECIPE')),
  constraint chk_todo_config_resource_status check (status in ('ACTIVE','DISABLED'))
) engine=InnoDB default charset=utf8mb4 collate=utf8mb4_unicode_ci;

